import itertools
SB=[0,5,10,45,50,55,100,105,110,115,150,200,205,250]
SW=[0,10,50,100,150,190,200]
FB=list(range(0,251,5)); FW=list(range(0,201,10))
AM=[-10,0,5]+list(range(10,221,10))
def run(a,B,W,disp,daily,feef,funds):
    if a<=0 or a%10: return 'inv'
    if daily(a,B,W): return 'daily'
    fee=feef(a,B,W)
    if funds(a,B,W,fee): return 'funds'
    if not disp: return 'cd'
    return ('ok',fee,B-a-fee,W+a)
ref=(lambda a,B,W:W+a>200, lambda a,B,W:5 if a>100 else 0, lambda a,B,W,f:a+f>B)
def check(m):
    def diff(Bs,Ws):
        n=0
        for a in AM:
            for B in Bs:
                for W in Ws:
                    for d in (0,1):
                        if run(a,B,W,d,*m)!=run(a,B,W,d,*ref): n+=1
        return n
    return diff(SB,SW), diff(FB,FW)
terms={'a':lambda a,B,W,f:a,'B':lambda a,B,W,f:B,'W':lambda a,B,W,f:W,'f':lambda a,B,W,f:f}
consts=[0,5,10,50,100,200,4,20]
import operator
ops={'>':operator.gt,'>=':operator.ge}
# expressions: sum of signed subsets of terms + const
exprs=[]
for r in range(1,4):
    for combo in itertools.combinations('aBWf',r):
        for signs in itertools.product([1,-1],repeat=r):
            exprs.append((combo,signs))
def mk(combo,signs,op,c):
    o=ops[op]
    return lambda a,B,W,f:o(sum(s*terms[t](a,B,W,f) for t,s in zip(combo,signs)),c)
res=[]
for combo,signs in exprs:
    for op in ops:
        for c in consts+[-x for x in consts]:
            p=mk(combo,signs,op,c)
            for site in ('daily','funds'):
                if site=='daily':
                    m=(lambda a,B,W,p=p:p(a,B,W,0),ref[1],ref[2])
                else:
                    m=(ref[0],ref[1],p)
                s,f=check(m)
                if s==0 and f>0: res.append((f,site,combo,signs,op,c))
# fee mutations
for combo,signs in exprs:
    if 'f' in combo: continue
    for op in ops:
        for c in consts+[-x for x in consts]:
          for k in (5,10):
            p=mk(combo,signs,op,c)
            m=(ref[0],lambda a,B,W,p=p,k=k:k if p(a,B,W,0) else 0,ref[2])
            s,f=check(m)
            if s==0 and f>0: res.append((f,'fee',combo,signs,op,c,k))
for r in sorted(res,reverse=True): print(r)
EOF
