    xforms[f'min{c}']=lambda x,c=c:min(x,c)
res=[]
V=['a','B','W']
def val(n,a,B,W): return {'a':a,'B':B,'W':W}[n]
# funds: T(x) op over transformed variables
for xa,xb,xw in itertools.product(xforms,repeat=3):
    if (xa,xb,xw).count('id')<2: continue
    A,Bx,Wx=xforms[xa],xforms[xb],xforms[xw]
    cands={
     'funds a+f>B':(ref[0],ref[1],lambda a,B,W,f:A(a)+f>Bx(B)),
