     'daily W+a>200':(lambda a,B,W:Wx(W)+A(a)>200,ref[1],ref[2]),
     'daily a>200-W':(lambda a,B,W:A(a)>Wx(200-W),ref[1],ref[2]),
     'daily W+a xf':(lambda a,B,W:Wx(W+A(a))>200,ref[1],ref[2]),
     'fee a>100':(ref[0],lambda a,B,W:5 if A(a)>100 else 0,ref[2]),
     'fee B>100':(ref[0],lambda a,B,W:5 if Bx(B)>100 else 0,ref[2]),
     'fee B>=100':(ref[0],lambda a,B,W:5 if Bx(B)>=100 else 0,ref[2]),
     'fundsfeeB':(ref[0],ref[1],lambda a,B,W,f:A(a)+(5 if Bx(B)>100 else 0)>B),
     'fundsfeeB2':(ref[0],ref[1],lambda a,B,W,f:A(a)>B-(5 if Bx(B)>100 else 0)),
     'fundsfeeBW':(ref[0],ref[1],lambda a,B,W,f:A(a)+(5 if Wx(W)+a>100 else 0)>B),
    }
